#[test]
fn every_test_file_is_compiled() {
    let listed = include_str!("all.rs");
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests");
    let mut missing = Vec::new();
    for entry in std::fs::read_dir(dir).expect("read tests/") {
        let name = entry
            .expect("dir entry")
            .file_name()
            .into_string()
            .expect("utf-8 name");
        if name.ends_with(".rs")
            && name != "all.rs"
            && !listed.contains(&format!("#[path = \"{name}\"]"))
        {
            missing.push(name);
        }
    }
    assert!(
        missing.is_empty(),
        "test files not compiled into tests/all.rs: {missing:?}; run python3 api/scripts/gen-test-binaries.py"
    );
}
